-- Checkout validates this coupon server-side in create_order().
on conflict (code) do update set percent_off=excluded.percent_off,
  min_subtotal=excluded.min_subtotal,active=excluded.active;

on conflict (slug) do nothing;

on conflict (name) do nothing;

on conflict (id) do nothing;

-- keep identity sequences ahead of the seeded ids
select setval(pg_get_serial_sequence('public.products','id'), greatest((select max(id) from public.products),1));
select setval(pg_get_serial_sequence('public.categories','id'), greatest((select max(id) from public.categories),1));
select setval(pg_get_serial_sequence('public.brands','id'), greatest((select max(id) from public.brands),1));
